import * as React from 'react';

// Create-mode description editor for the Create Task page.
// Reproduces the Task Popup's boxes structure ("Add New Box" / "Add Sub-Text Box")
// with Title/text content only, and emits the exact FeedBackDescriptions JSON shape
// the popup uses so a created task opens and edits correctly there:
//   - box object shape mirrors shared-ui FroalaCommnetBoxes.tsx:144-157 (content in `Title`)
//   - nested sub-boxes under Subtext[] (EditTaskPopup.tsx:1736-1739)
// Edit-only machinery (QA / approval / traffic-light / comments authoring / live SP reads)
// is intentionally omitted at create time; the corresponding fields are emitted at safe
// defaults so the popup can render/edit the content without change. This component is
// controlled: it owns no persistence and calls onChange with the full boxes array.

type Box = {
    Completed: string;
    Title: string;
    text: string;
    SeeAbove: string;
    Phone: string;
    LowImportance: string;
    HighImportance: string;
    QATested: boolean;
    isShowLight: string;
    TaskCreatedForThis: boolean;
    qaComment: string;
    qaImages: string[];
    isShowComment: boolean;
    Comments: any[];
    Id: string;
    Subtext?: Box[];
};

interface ICreateTaskDescriptionProps {
    value?: Box[];
    onChange: (boxes: Box[]) => void;
}

let uidCounter = 0;
const newId = (): string => `${Date.now()}${(uidCounter = (uidCounter + 1) % 100000)}`;

const makeBox = (withSubtext: boolean): Box => ({
    Completed: '',
    Title: '',
    text: '',
    SeeAbove: '',
    Phone: '',
    LowImportance: '',
    HighImportance: '',
    QATested: false,
    isShowLight: '',
    TaskCreatedForThis: false,
    qaComment: '',
    qaImages: [],
    isShowComment: false,
    Comments: [],
    Id: newId(),
    ...(withSubtext ? { Subtext: [] } : {}),
});

const textareaClass =
    'w-full border border-[#ccc] bg-white px-3 py-1.5 text-sm text-[#333] outline-none placeholder:text-[#999] focus:border-(--SiteColor)';
const addBtnClass =
    'inline-flex items-center justify-center border border-(--SiteColor) bg-(--SiteColor) px-3 py-1.5 text-sm font-medium text-white cursor-pointer';

export default function CreateTaskDescription(props: ICreateTaskDescriptionProps): React.ReactElement {
    const boxes: Box[] = Array.isArray(props.value) ? props.value : [];

    const emit = (next: Box[]): void => {
        props.onChange(next);
    };

    const addBox = (): void => {
        emit([...boxes, makeBox(true)]);
    };

    const removeBox = (idx: number): void => {
        emit(boxes.filter((_, i) => i !== idx));
    };

    const changeBoxTitle = (idx: number, val: string): void => {
        emit(boxes.map((b, i) => (i === idx ? { ...b, Title: val } : b)));
    };

    const addSubBox = (idx: number): void => {
        emit(boxes.map((b, i) => (i === idx ? { ...b, Subtext: [...(b.Subtext || []), makeBox(false)] } : b)));
    };

    const removeSubBox = (idx: number, subIdx: number): void => {
        emit(
            boxes.map((b, i) =>
                i === idx ? { ...b, Subtext: (b.Subtext || []).filter((_, s) => s !== subIdx) } : b,
            ),
        );
    };

    const changeSubBoxTitle = (idx: number, subIdx: number, val: string): void => {
        emit(
            boxes.map((b, i) =>
                i === idx
                    ? { ...b, Subtext: (b.Subtext || []).map((s, si) => (si === subIdx ? { ...s, Title: val } : s)) }
                    : b,
            ),
        );
    };

    return (
        <div className="mt-2 w-full">
            {boxes.length === 0 ? (
                <button type="button" className={addBtnClass} onClick={addBox}>
                    Add New Box
                </button>
            ) : (
                <div className="space-y-3">
                    {boxes.map((box, i) => (
                        <div key={box.Id} className="border border-[#e0e0e0] bg-[#fafafa] p-3">
                            <div className="flex items-start gap-2">
                                <textarea
                                    className={textareaClass}
                                    rows={2}
                                    placeholder="Describe this point"
                                    value={box.Title}
                                    onChange={(e) => changeBoxTitle(i, e.target.value)}
                                />
                                <span
                                    title="Remove box"
                                    className="svg__iconbox svg__icon--trash hreflink cursor-pointer mt-1"
                                    onClick={() => removeBox(i)}
                                ></span>
                            </div>

                            {(box.Subtext || []).length > 0 && (
                                <div className="mt-2 space-y-2 pl-4">
                                    {(box.Subtext || []).map((sub, s) => (
                                        <div key={sub.Id} className="flex items-start gap-2">
                                            <textarea
                                                className={textareaClass}
                                                rows={1}
                                                placeholder="Sub-text"
                                                value={sub.Title}
                                                onChange={(e) => changeSubBoxTitle(i, s, e.target.value)}
                                            />
                                            <span
                                                title="Remove sub-text box"
                                                className="svg__iconbox svg__icon--trash hreflink cursor-pointer mt-1"
                                                onClick={() => removeSubBox(i, s)}
                                            ></span>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <div className="mt-2">
                                <a
                                    className="text-xs text-(--SiteColor) hover:underline font-medium cursor-pointer"
                                    onClick={() => addSubBox(i)}
                                >
                                    + Add Sub-Text Box
                                </a>
                            </div>
                        </div>
                    ))}
                    <button type="button" className={addBtnClass} onClick={addBox}>
                        Add New Box
                    </button>
                </div>
            )}
        </div>
    );
}

